enum Outcome = {Denied, Approved, CounterOffer};

var int: priyaCreditScore = 680;
var int: samCreditScore = 750;
var int: combinedIncome = 9000;
var int: combinedDebt = 3200;
var int: policyLimit = 0; % This should represent the actual policy limit value

var Outcome: result;

% Determine the credit tier
var int: creditTier = min(priyaCreditScore, samCreditScore);
constraint creditTier >= 600 -> (result != Denied);

% Calculate the Debt-to-Income (DTI) ratio
var float: dti = combinedDebt / (combinedIncome * 1.0);
constraint dti <= 0.43 -> (result != Denied);

% Evaluate the loan outcome
constraint (result != Denied) ->
    (if (combinedDebt > policyLimit) then result := CounterOffer else result := Approved)

% Since there is a known outcome:
constraint result = CounterOffer;

